// Note: "reseller" is no longer a role - it's now a capability based on reseller_profiles table
// VTID-01230: developer + infra are super-admin-grantable only
// VTID-03832: "backoffice" sits between staff and admin (BackOffice plan decision 4b):
//   admin/developer/infra inherit BackOffice; staff needs an explicit grant;
//   backoffice cannot reach /admin. Backend has 8 roles total; the gateway mirror
//   is services/gateway/src/constants/vitana-roles.ts.
export type UserRole = "community" | "patient" | "professional" | "staff" | "backoffice" | "admin" | "developer" | "infra";

export const ROLE_LADDER: UserRole[] = ['community', 'patient', 'professional', 'staff', 'backoffice', 'admin', 'developer', 'infra'];

// VTID-01230 safety net: an Exafy super-admin always sees every role, even
// if the RPC is unavailable — the switcher must never disappear for them.
export const ALL_ROLES_SUPER_ADMIN: UserRole[] = ROLE_LADDER;

// No phone-sized home: BackOffice is desktop-only (VTID-03973), developer and
// infra land on the gateway's external Command Hub.
export const MOBILE_EXCLUDED_ROLES: UserRole[] = ['backoffice', 'developer', 'infra'];

export const isUserRole = (r: string): r is UserRole => (ROLE_LADDER as string[]).includes(r);

export function computeAvailableRoles(input: {
  granted: readonly string[] | undefined;
  isExafyAdmin: boolean;
  isPatient: boolean;
  isMobile: boolean;
}): UserRole[] {
  const set = new Set<UserRole>(input.isExafyAdmin ? ALL_ROLES_SUPER_ADMIN : (input.granted ?? []).filter(isUserRole));
  // Everyone is a community member by definition — it must always be a way back.
  set.add('community');
  if (input.isPatient) set.add('patient');
  return ROLE_LADDER.filter((r) => set.has(r) && !(input.isMobile && MOBILE_EXCLUDED_ROLES.includes(r)));
}

export interface BusinessSwitchEntry {
  orgId: string;
  orgName: string;
  role: string;
}

/** One sheet entry per business membership, in the order the API lists them. */
export function computeBusinessEntries(orgs: ReadonlyArray<{ id: string; display_name: string; role: string }>): BusinessSwitchEntry[] {
  return orgs.map((o) => ({ orgId: o.id, orgName: o.display_name, role: o.role }));
}

/**
 * Where ProfileDrawer.handleRoleChange goes after a successful role switch.
 * Pulled out so the mapping can be unit tested without rendering the whole
 * drawer. Everything but developer/infra is an in-app route, reached with
 * react-router's navigate() (VTID-03916); developer/infra resolve to an
 * absolute, cross-origin URL (the gateway's Command Hub) that navigate()
 * cannot reach — isExternalRoleSwitchDestination() below tells the caller
 * which navigation primitive to use.
 */
export function getRoleSwitchDestination(role: UserRole): string {
  switch (role) {
    case "admin":
    case "staff":
      return "/admin";
    case "backoffice":
      // VTID-03832: BackOffice home (route shell lands in the /backoffice skeleton VTID)
      return "/backoffice/dashboard";
    case "professional":
      return "/professional/dashboard";
    case "patient":
      return "/patient/dashboard";
    case "developer":
    case "infra": {
      // Technical, cross-tenant roles with no in-app landing screen of their
      // own — they land on the gateway's Command Hub, not community. Falls
      // back to /home only if the gateway base isn't configured at all.
      const commandHubUrl = (() => null)();
      return commandHubUrl || "/home";
    }
    case "community":
    default:
      return "/home";
  }
}

export function isExternalRoleSwitchDestination(destination: string): boolean {
  return /^https?:\/\//.test(destination);
}
